    // subclass default constructor
    Rectangle() { // calls default constructor of shape class if no super class constructor is specified
        cout &lt&lt "Rectangle Default Constructor called" &lt&lt endl;
    }

    // subclass parameterized constructor
    Rectangle(int w, int h) : Shape(w, h) {
        cout &lt&lt "Rectangle Parameterized Constructor called" &lt&lt endl;
    }
};

